sources.nearObj:
function nearObj(types, range=22){
  let best=null, bd=range;
  for(const o of objects){
    if(!types.includes(o.type)) continue;
    const cx = o.x + (o.w?o.w/2:0), cy = o.y + (o.h?o.h/2:0);
    const d = Math.hypot(player.x-cx, player.y-cy);
    if(d<bd){ bd=d; best=o; }
  }
  return best;
}

sources.inShade:
function inShade(){
  // Mesma elipse desenhada por drawTree — inclusive o deslocamento pelo sol.
  const sv = (typeof sunShadowVec === 'function') ? sunShadowVec() : null;
  for(const o of objects) if(o.type==='tree'){
    const e = treeShadowEllipse(o, sv);
    const dx = (player.x - e.cx)/e.rx, dy = (player.y - e.cy)/e.ry;
    if(dx*dx + dy*dy < 1) return true;
  }
  // House/barn shadow (south side)
  for(const o of objects) if(o.type==='house'||o.type==='barn'){
    if(player.x>o.x && player.x<o.x+o.w && player.y>o.y+o.h && player.y<o.y+o.h+12) return true;
  }
  return false;
}

sources.nearShelter:
function nearShelter(){
  if(isIndoor()) return true;
  if(nearObj(['house','barn'], 50)) return true;
  for(const o of objects) if((o.type==='fireplace' || o.type==='i_fireplace' || o.type==='b_stove') && o.lit && Math.hypot(player.x-o.x, player.y-o.y)<55) return true;
  return false;
}

sources.nearFire:
function nearFire(){
  for(const o of objects) if(o.type==='fireplace' && o.lit && Math.hypot(player.x-o.x, player.y-o.y)<45) return true;
  return false;
}

sources.fireWarmthFactor:
function fireWarmthFactor(){
  let best = 0;
  for(const o of objects){
    if((o.type!=='fireplace' && o.type!=='i_fireplace' && o.type!=='b_stove') || !o.lit) continue;
    const d = Math.hypot(player.x-o.x, player.y-o.y);
    if(d < 90) best = Math.max(best, 1 - d/90);
  }
  return Math.max(0, Math.min(1, best));
}

sources.nearestObjectDistance:
function nearestObjectDistance(type){
  let nearest = Infinity;
  for(const o of objects){
    if(o.type !== type) continue;
    const d = Math.hypot(player.x - o.x, player.y - o.y);
    if(d < nearest) nearest = d;
  }
  return nearest;
}

sources.findNearestLitFire:
function findNearestLitFire(){
  let nearest = null, dist = Infinity;
  for(const o of objects){
    if(!['fireplace','mtn_fire','i_fireplace','b_stove'].includes(o.type) || (!o.lit&&!['i_fireplace','b_stove'].includes(o.type))) continue;
    const d = Math.hypot(player.x - o.x, player.y - o.y);
    if(d < dist){ dist = d; nearest = o; }
  }
  return { obj: nearest, dist };
}

sources.isScarecrowNearby:
function isScarecrowNearby(x, y){
  for(const o of objects){
    if(o.type !== 'scarecrow') continue;
    if(Math.hypot(o.x - x, o.y - y) < 80) return true;
  }
  return false;
}

footprint:
function footprint(o){
 switch(o.type){
  case 'house':case 'barn':case 'story_seed_house':return{x:o.x-3,y:o.y+4,w:o.w+6,h:o.h-7};
  case 'mtn_cabin':return{x:o.x-33,y:o.y-35,w:64,h:38};
  case 'tree':case 'fx_fruittree':return{x:o.x-5,y:o.y-3,w:10,h:12};
  case 'mtn_pine':return{x:o.x-4,y:o.y-7,w:8,h:10};
  case 'des_palm':return{x:o.x-3,y:o.y-7,w:8,h:11};
  case 'mtn_rock':return{x:o.x-13,y:o.y-10,w:26,h:13};
  case 'des_mesa':return{x:o.x-18,y:o.y-14,w:36,h:18};
  case 'des_cactus':return{x:o.x-6,y:o.y-7,w:12,h:10};
  case 'world_ridge':return{x:o.x,y:o.y-o.rise+8,w:o.w,h:o.rise+o.h-8};
  default:return null;
 }
}

